package com.cenedu.backend.ai.problem.render;
import com.cenedu.backend.domain.problem.authoring.diagram.*; import com.cenedu.backend.domain.problem.authoring.semantic.evaluation.SemanticResolvedValue; import java.util.*;
public final class CoordinateGraphSvgRenderer { public String render(CoordinateGraphDiagramSpecV1 s){return render(s,Map.of());} public String render(CoordinateGraphDiagramSpecV1 s,Map<String,SemanticResolvedValue> values){int p=s.viewport().padding(),w=s.viewport().width(),h=s.viewport().height(),cx=w/2,cy=h/2;var b=new StringBuilder("<line x1=\"").append(p).append("\" y1=\"").append(cy).append("\" x2=\"").append(w-p).append("\" y2=\"").append(cy).append("\" stroke=\"#000000\"/>");for(var f:s.functions()){double k=num(values,f.coefficientKey(),1);if(f.functionKind()==CoordinateFunctionKind.INVERSE_PROPORTION)b.append(path(s,p,p,cx-2,cy-1,k,true)).append(path(s,cx+2,p,w-p,cy+1,k,true));else b.append(path(s,p,p,w-p,h-p,k,false));}return b.toString();}private String path(CoordinateGraphDiagramSpecV1 s,int x1,int y1,int x2,int y2,double k,boolean inverse){var b=new StringBuilder("<path d=\"M ");for(int i=0;i<=8;i++){double t=i/8.0,x=x1+(x2-x1)*t,y=inverse?y1+(y2-y1)*t:y1+(y2-y1)*t*k;int yi=(int)PlotClipper.clamp(y,s.viewport().padding(),s.viewport().height()-s.viewport().padding());b.append((int)x).append(" ").append(yi).append(i==8?"":" L ");}return b.append("\" fill=\"none\" stroke=\"#000000\"/>").toString();}private double num(Map<String,SemanticResolvedValue> v,String k,double d){try{return Double.parseDouble(v.get(k).canonicalValue());}catch(Exception e){return d;}}}
